@@ -452,6 +452,7 @@ struct ipv6_txoptions *ipv6_renew_options(struct sock *sk,
 					  struct ipv6_txoptions *opt,
 					  int newtype,
 					  struct ipv6_opt_hdr *newopt);
+bool ipv6_hopopt_contains_jumbo(const struct ipv6_opt_hdr *hopopt);
