+	if (usb_endpoint_num(in) != 1)
+		return false;
+
+	/* Check Tx endpoint address */
+	if (usb_endpoint_num(out) != 2)
+		return false;
+
+	/* Check interrupt endpoint address */
+	if (usb_endpoint_num(intr) != 3)
+		return false;
+
+	return true;
